import * as React from 'react';
import { CommonProps } from '../utility/commonProps';
export interface ListProps extends Omit<React.ComponentPropsWithoutRef<'ul'>, 'className' | 'style'>, CommonProps {
    /**
     * The content for the list.
     */
    children: React.ReactNode;
    /**
     * Boolean to toggle divider between each ListItem.
     *
     * @default true
     */
    showDivider?: boolean;
}
/**
 * Lists are continuous, vertical indexes of related information.
 *
 * - {@link https://livingdesign.walmart.com/components/list/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/list/react/ React documentation}
 *
 * ### Content
 *
 * The List accepts List Items through the `children` prop:
 *
 * ```tsx
 * <List>
 *   <ListItem title='Dog' />
 *   <ListItem title='Cat' />
 *   <ListItem title='Mouse' />
 * </List>
 * ```
 *
 * #### Divider between ListItems.
 *
 * The List provides `showDivider` prop to toggle the divider to sepepate the ListItems.
 *
 * ```tsx
 * <List showDivider={false}> (default)
 *   <ListItem title='Dog' />
 *   <ListItem title='Cat' />
 *   <ListItem title='Mouse' />
 * </List>
 * <List showDivider={true}>
 *   <ListItem title='Dog' />
 *   <ListItem title='Cat' />
 *   <ListItem title='Mouse' />
 * </List>
 * ```
 */
export declare const List: React.FunctionComponent<ListProps>;
